```c
int read_strings(const char* filename, char *s[static 100]) {
    FILE *f = fopen(filename, "r");
    int n = 0;      // number of lines read so far
    size_t j = 0;   // index of the next character in the current line
    int c;
    while ((c = fgetc(f)) != EOF) {
        if (c == '\n') {
            if (n < 100) {
                s[n][j] = '\0';
            }
            n++;
            j = 0;
        }
        else {
            if (n < 100) {
                s[n][j] = c;
            }
            j++;
        }
    }
    if (j > 0) {    // last line did not end with a newline
        if (n < 100) {
            s[n][j] = '\0';
        }
        n++;
    }
    fclose(f);
    return n;
}
```

This stores each line **without** its newline. Because no line length is given, it reads character by character so lines past the 100th can still be counted without storing them. A shorter `fgets` version that assumes some maximum line length (6(d) later says lines are under 100 characters) is also acceptable:

```c
int read_strings(const char* filename, char *s[static 100]) {
    FILE *f = fopen(filename, "r");
    char extra[1000];   // lines after the 100th are read here and discarded
    int n = 0;
    while (fgets(n < 100 ? s[n] : extra, 1000, f) != NULL) {
        n++;
    }
    fclose(f);
    return n;
}
```

(this one keeps the newline at the end of each stored line). Both tested with 4 lines, a last line without a newline, an empty file, and 120 lines.

